SET DEFINE OFF
-- Synthetic source database for the telco demo (Subscriber churn and ARPU data product)
-- Dialect: oracle. Generated by ADEF; all values are synthetic.

-- Schema-only accounts: they own the tables and cannot log in (no passwords).
CREATE USER BSS NO AUTHENTICATION QUOTA UNLIMITED ON USERS;
CREATE USER CRM NO AUTHENTICATION QUOTA UNLIMITED ON USERS;
CREATE USER USAGE NO AUTHENTICATION QUOTA UNLIMITED ON USERS;

-- Subscribers
CREATE TABLE CRM.SUBSCRIBER (
    SUBSCRIBER_ID              VARCHAR2(20)       NOT NULL,
    MSISDN                     VARCHAR2(15)      ,
    FULL_NAME                  VARCHAR2(200)     ,
    SEGMENT                    VARCHAR2(20)      ,
    ACTIVATION_DATE            DATE              ,
    STATUS                     VARCHAR2(12)      ,
    EMAIL_ADDRESS              VARCHAR2(200)     ,
    PREFERRED_LANGUAGE         VARCHAR2(5)       ,
    CREATED_BY                 VARCHAR2(40)      ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_SUBSCRIBER PRIMARY KEY (SUBSCRIBER_ID)
);

COMMENT ON COLUMN CRM.SUBSCRIBER.EMAIL_ADDRESS IS 'Contact email';
COMMENT ON COLUMN CRM.SUBSCRIBER.PREFERRED_LANGUAGE IS 'ISO language code';
COMMENT ON COLUMN CRM.SUBSCRIBER.CREATED_BY IS 'Audit user';
COMMENT ON COLUMN CRM.SUBSCRIBER.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Product subscriptions
CREATE TABLE BSS.SUBSCRIPTION (
    SUBSCRIPTION_ID            VARCHAR2(20)       NOT NULL,
    SUBSCRIBER_ID              VARCHAR2(20)      ,
    PRODUCT_CODE               VARCHAR2(12)      ,
    START_DATE                 DATE              ,
    END_DATE                   DATE              ,
    MONTHLY_FEE                NUMBER(12,2)      ,
    CONTRACT_TERM_MONTHS       NUMBER(10)        ,
    SALES_CHANNEL              VARCHAR2(20)      ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_SUBSCRIPTION PRIMARY KEY (SUBSCRIPTION_ID)
);

COMMENT ON COLUMN BSS.SUBSCRIPTION.CONTRACT_TERM_MONTHS IS 'Commitment term';
COMMENT ON COLUMN BSS.SUBSCRIPTION.SALES_CHANNEL IS 'Retail, online or telesales';
COMMENT ON COLUMN BSS.SUBSCRIPTION.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Product catalogue
CREATE TABLE BSS.PRODUCT_CATALOG (
    PRODUCT_CODE               VARCHAR2(12)       NOT NULL,
    PRODUCT_NAME               VARCHAR2(100)     ,
    PRODUCT_FAMILY             VARCHAR2(30)      ,
    LIST_PRICE                 NUMBER(12,2)      ,
    LAUNCH_DATE                DATE              ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_PRODUCT_CATALOG PRIMARY KEY (PRODUCT_CODE)
);

COMMENT ON COLUMN BSS.PRODUCT_CATALOG.LAUNCH_DATE IS 'Product launch date';
COMMENT ON COLUMN BSS.PRODUCT_CATALOG.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Aggregated daily usage per subscriber
CREATE TABLE USAGE.DAILY_USAGE_SUMMARY (
    SUBSCRIBER_ID              VARCHAR2(20)       NOT NULL,
    USAGE_DATE                 DATE               NOT NULL,
    DATA_MB                    NUMBER(14,2)      ,
    VOICE_MIN                  NUMBER(10,2)      ,
    SMS_COUNT                  NUMBER(10)        ,
    ROAMING_FLAG               NUMBER(1)         ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_DAILY_USAGE_SUMMARY PRIMARY KEY (SUBSCRIBER_ID, USAGE_DATE)
);

COMMENT ON COLUMN USAGE.DAILY_USAGE_SUMMARY.SMS_COUNT IS 'SMS sent';
COMMENT ON COLUMN USAGE.DAILY_USAGE_SUMMARY.ROAMING_FLAG IS 'Any roaming usage that day';
COMMENT ON COLUMN USAGE.DAILY_USAGE_SUMMARY.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Port-out and disconnection events
CREATE TABLE CRM.CHURN_EVENT (
    SUBSCRIBER_ID              VARCHAR2(20)       NOT NULL,
    CHURN_DATE                 DATE              ,
    CHURN_REASON               VARCHAR2(40)      ,
    WIN_BACK_OFFER_CODE        VARCHAR2(12)      ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_CHURN_EVENT PRIMARY KEY (SUBSCRIBER_ID)
);

COMMENT ON COLUMN CRM.CHURN_EVENT.WIN_BACK_OFFER_CODE IS 'Retention offer presented';
COMMENT ON COLUMN CRM.CHURN_EVENT.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';
